entries[32375] = { ["name"] = "Massenbannung", ["text"] = "13% von Grundmana 30 Meter Reichweite\nWirken in 1.5 sek. 15 sek. Abklingzeit\nBannt Magie in einem Radius von 15 Metern. Entfernt alle schädlichen Zauber von verbündeten Zielen und 1 nützlichen Zauber von gegnerischen Zielen. Wirkt auf bis zu 10 verbündete und 10 gegnerische Ziele. [ Glyphe 'Massenbannung' : Dieser Bannzauber ist mächtig genug, magische Effekte zu entfernen, die normalerweise nicht gebannt werden können ]" }
entries[32376] = { ["name"] = "Weichklopfen", ["text"] = "Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nHackt auf die Rüstung des Gegners ein und verringert sie um 24 pro 'Rüstung zerreißen'. Kann bis zu 5-mal angewendet werden. Hält 30 Sek. lang an." }
entries[32378] = { ["name"] = "Filetieren", ["text"] = "Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nVerursacht 300% Waffenschaden und verwundet das Ziel, verringert außerdem die Wirksamkeit jeglicher Heilung 5 Sek. lang um 50%." }
entries[32379] = { ["name"] = "Schattenwort: Tod", ["text"] = "2.6% von Grundmana 40 Meter Reichweite\nSofort 8 sek. Abklingzeit\nEin Wort der bindenden Dunkelheit, das dem Ziel 1 Schattenschaden zufügt [ Gedankenschinden : und eine Schattenkugel erzeugt ]. Kann nur gegen Ziele mit weniger als 20% Gesundheit eingesetzt werden. [ Gedankenschinden : Wenn das Ziel durch diesen Zauber nicht stirbt, wird die Abklingzeit sofort abgeschlossen, dieser zusätzliche Einsatz von 'Schattenwort: Tod' gewährt Euch aber keine Schattenkugel. Dieser Effekt hat eine Abklingzeit von 9 Sek ]" }
