entries[32397] = { ["name"] = "Knotenhautrüstungsset", ["text"] = "Wirken in 3 sek.\nBenötigt Brust, Brust, Handschuhe, Hosen, Stiefel\nErhöht die Ausdauer eines Gegenstands, der an Brust, Beinen, Händen oder Füßen getragen wird, dauerhaft um 8 ." }
entries[32398] = { ["name"] = "Rüstungsset des Verteidigers", ["text"] = "Wirken in 3 sek.\nBenötigt Brust, Brust, Handschuhe, Hosen, Stiefel\nErhöht das Ausweichen eines Gegenstands, der an Brust, Beinen, Händen oder Füßen getragen wird, dauerhaft um 8 .\n\nDurch das Anbringen des Rüstungssets wird der Gegenstand seelengebunden." }
entries[32399] = { ["name"] = "Rüstungsset des Magisters", ["text"] = "Wirken in 3 sek.\nBenötigt Brust, Brust, Handschuhe, Hosen, Stiefel\nErhöht die Willenskraft eines Gegenstands, der an Brust, Beinen, Händen oder Füßen getragen wird, dauerhaft um 8 .\n\nDurch das Anbringen des Rüstungssets wird der Gegenstand seelengebunden." }
entries[32400] = { ["name"] = "Läuterung", ["text"] = "175 Mana 30 Meter Reichweite\nSofort\nReinigt ein verbündetes Ziel und hebt dabei 1 Gifteffekt, 1 Krankheitseffekt und 1 Magieeffekt auf. Entfernt zusätzlich spezielle Schwächungen von Ozkreaturen." }
entries[32404] = { ["name"] = "Flammenschutz", ["text"] = "30 Meter Reichweite\nSofort\nUmgibt einen Verbündeten mit einem Flammenschild, der allen nahen Feinden alle 5 Sek. 57 Feuerschaden zufügt. Hält 6 Sek. lang an." }
entries[32405] = { ["name"] = "Mal des Shalasverstecks", ["text"] = "Unbegrenzte Reichweite\nSofort\nIhr wurdet vom Zauberschutz des Shalasverstecks identifiziert und markiert." }
