entries[32408] = { ["name"] = "Rauchsignale erzeugen", ["text"] = "10 Meter Reichweite\nWirken in 10 sek.\nErzeugt Rauchsignale, wenn es am lodernden Scheiterhaufen der Totschläger auf dem Hof des Lachenden Schädels benutzt wird." }
entries[32409] = { ["name"] = "Schattenwort: Tod", ["text"] = "Sofort\nEin Wort der bindenden Dunkelheit, das sowohl dem Ziel als auch dem Zaubernden 627 Schattenschaden zufügt.\n\nWenn das Ziel über weniger als 20% Gesundheit verfügt, erleidet es den vierfachen Schaden.\n\nWenn das Ziel durch diesen Zauber stirbt, erleidet der Zaubernde keinen Schaden." }
