entries[32592] = { ["name"] = "Massenbannung", ["text"] = "30 Meter Reichweite\nSofort\nBannt Magie in einem Radius von 15 Metern. Entfernt alle schädlichen Zauber von verbündeten Zielen und 1 nützlichen Zauber von gegnerischen Zielen. Dieser Bannzauber ist mächtig genug, magische Effekte zu entfernen, die normalerweise nicht gebannt werden können." }
entries[32595] = { ["name"] = "Machtwort: Schild", ["text"] = "110 Mana 40 Meter Reichweite\nSofort\nUmgibt einen Verbündeten mit einem Schild, der bis zu 30 Sek. lang bestehen bleibt und maximal 411 körperlichen oder magischen Schaden absorbiert. Solange der Schild hält, werden Zauber nicht durch körperliche Angriffe unterbrochen." }
