entries[33831] = { ["name"] = "Naturgewalt", ["text"] = "40 Meter Reichweite\nSofort 20 sek. Wiederaufladung\n3 Aufladungen\nBeschwört einen Treant, der Euer aktuelles Ziel sofort für 30 Sek. bewegungsunfähig macht. Der Treant setzt 'Zorn' gegen das Ziel ein und fügt ihm dadurch alle 2 Sek. [ 1930 + (Zaubermacht * 0.375)]) bis [ 2175 + (Zaubermacht * 0.375)]) Naturschaden zu. Hält 15 Sek. lang an. Maximal 3 Aufladungen." }
entries[33832] = { ["name"] = "Arkane Geschosse", ["text"] = "235 Mana 30 Meter Reichweite\nKanalisiert (Wirken in 5 sek.)\nSchleudert magische Geschosse auf einen Feind und verursacht 5 Sek. lang pro Sekunde Arkanschaden." }
